export function createTerms(React){const{createElement:h}=React;return function Terms(){const sections=[['Dự án cá nhân, chia sẻ miễn phí','MONDAY là dự án do cá nhân phát triển và chia sẻ miễn phí. Đây không phải dịch vụ có cam kết về thời gian hoạt động, hỗ trợ hoặc chất lượng đầu ra. Dịch vụ AI bên thứ ba có thể thu phí riêng.'],['Chấp thuận điều khoản','Việc tiếp tục sử dụng ứng dụng thể hiện bạn đã đọc và đồng ý các điều khoản được công bố tại đây, trong phạm vi pháp luật cho phép. Nếu không đồng ý, hãy ngừng sử dụng. Các thay đổi điều khoản sẽ được công bố trong ứng dụng.'],['Quyền đối với nội dung','Bạn chịu trách nhiệm về quyền sử dụng ảnh, video, âm thanh, thương hiệu, prompt và dữ liệu tải lên; cần có sự đồng ý phù hợp của người xuất hiện trong nội dung. Không dùng ứng dụng để xâm phạm bản quyền, quyền riêng tư, giả mạo, quấy rối hoặc thực hiện hành vi trái pháp luật.'],['Kết quả AI và quyền thương mại','Kết quả có thể sai, thay đổi danh tính, thiết kế hoặc trùng lặp với nội dung khác. Ứng dụng không bảo đảm tính độc quyền, khả năng đăng ký quyền hay quyền khai thác thương mại. Bạn cần kiểm tra đầu ra và điều khoản của dịch vụ AI trước khi sử dụng hoặc công bố.'],['Giới hạn trách nhiệm','Trong phạm vi pháp luật cho phép, tác giả không chịu trách nhiệm đối với tranh chấp bản quyền phát sinh từ nội dung người dùng, mất dữ liệu, chi phí dịch vụ, gián đoạn, mất lợi nhuận hoặc thiệt hại do sử dụng ứng dụng. Điều khoản này không loại trừ trách nhiệm hoặc quyền của người dùng mà pháp luật không cho phép loại trừ.'],['Dữ liệu và dịch vụ kết nối','Khi bạn chủ động tạo nội dung, ảnh và prompt liên quan được gửi tới dịch vụ đã kết nối. Việc lưu trữ, xử lý và bảo mật tại đó tuân theo chính sách của nhà cung cấp. Không tải lên bí mật hoặc dữ liệu nhạy cảm nếu chưa kiểm tra quyền và chính sách phù hợp.'],['Tài khoản, chi phí và sao lưu','Bạn tự quản lý tài khoản, khóa kết nối, hạn mức và chi phí. Sao lưu dữ liệu quan trọng trước khi cập nhật hoặc xóa. Không chia sẻ khóa truy cập; không sử dụng tài khoản của người khác khi chưa được cho phép.'],['Góp ý và liên hệ','Bạn có thể gửi lỗi hoặc yêu cầu xem xét nội dung qua monday.directory@gmail.com. Việc xử lý và cập nhật được thực hiện theo khả năng của dự án cá nhân.']];return h('div',{className:'terms-document'},h('p',{className:'terms-intro'},'Điều khoản sử dụng · Cập nhật 01/11/2026'),...sections.map(([title,text],i)=>h('section',{key:title},h('h3',null,(i+1)+'. '+title),h('p',null,text))));};}
